package org.pms.silverocean.controller;
import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.pms.silverocean.common.ResponseCode;import org.pms.silverocean.controller.wrappers.ResponseDTO;import org.pms.silverocean.service.I18NService;import org.pms.silverocean.service.leasefinance.*;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/lease/finance") @RequiredArgsConstructor public class LeaseFinanceController{private final LeaseFinanceService service;private final I18NService i18n;@PostMapping public ResponseEntity<ResponseDTO>create(@RequestBody @Valid LeaseFinanceModels.Create request){return ok(service.create(request));}@GetMapping("/{leaseId}")public ResponseEntity<ResponseDTO>view(@PathVariable long leaseId){return ok(service.view(leaseId));}@PutMapping("/{leaseId}/late-fee-rule")public ResponseEntity<ResponseDTO>rule(@PathVariable long leaseId,@RequestBody @Valid LeaseFinanceModels.Rule request){return ok(service.setRule(leaseId,request));}@PostMapping("/late-fee/assess")public ResponseEntity<ResponseDTO>assess(@RequestBody @Valid LeaseFinanceModels.Assess request){return ok(service.assess(request));}private ResponseEntity<ResponseDTO>ok(Object value){return ResponseEntity.ok(new ResponseDTO(true,ResponseCode.GENERAL_SUCCESS.getCode(),i18n.getLocalizedMessage(ResponseCode.GENERAL_SUCCESS),value));}}
